fn make_runner_factory(
    core: Arc<CoreClient>,
    notify: Arc<Notify>,
    approvals: Arc<ApprovalGate>,
    catalog: UserConfig,
    session_id: String,
    cwd: PathBuf,
    scripts: Option<HashMap<String, Vec<Step>>>,
    barriers: BarrierRegistry,
    usage_probes: UsageProbes,
    model_overrides: ModelOverrides,
    session_profiles: Arc<Mutex<HashMap<String, ModelProfile>>>,
) -> RunnerFactory {
    Box::new(move |agent: &AgentSpec| {
        if let Some(scripts) = &scripts {
            let steps = scripts.get(&agent.id).cloned().unwrap_or_else(|| vec![Step::End]);
            return Ok(ScriptedMember::new(&agent.id, steps, barriers.clone()));
        }
        // feature 5 (/model): a session-level override wins over the profile
        let ov = model_overrides.lock().unwrap().get(&agent.id).cloned().unwrap_or_default();
        let profile_name = ov.profile.as_ref().unwrap_or(&agent.model_profile);
        // D-30: member-named session profiles shadow user-config profiles
        let profile: Option<ModelProfile> = session_profiles
            .lock()
            .unwrap()
            .get(profile_name)
            .cloned()
            .or_else(|| catalog.models.get(profile_name).cloned());
        if agent.runtime_kind == RuntimeKind::Codex {
            let opts = codex_options(agent, profile.as_ref(), &ov, &session_id, &cwd)?;
            let runner = CodexRunner::new(
                opts,
                core.clone(),
                approvals.clone(),
                notify.clone(),
            );
            let probe = runner.clone();
            usage_probes
                .lock()
                .unwrap()
                .insert(agent.id.clone(), Box::new(move || probe.usage_snapshot()));
            return Ok(runner);
        }
        let Some(profile) = profile else {
            return Err(format!("unknown model profile {}", agent.model_profile));
        };
        let profile = apply_model_override(profile, &ov);
        let agent_json = serde_json::to_value(agent).map_err(|e| e.to_string())?;
        let bound = crate::bound::BoundTools::load(&catalog, &agent.tool_bindings)?;
        // a required web service that cannot load fails the member, not the call;
        // the resolved set is also what the model gets advertised, so an explicit
        // binding name (anything but the literal "web") still exposes the tools
        let web = crate::tools::web_tools(&catalog, &agent.tool_bindings)?;
        let context = member_context(&catalog, &cwd, &session_id, agent);
        let runner = ChatRunner::new(
            &agent_json,
            profile,
            Some(member_root(agent, &cwd, &session_id)?.to_string_lossy().into_owned()),
            notify.clone(),
            bound,
            context,
            (web.search.is_some(), web.fetch.is_some()),
        );
        let probe = runner.clone();
        usage_probes
            .lock()
            .unwrap()
            .insert(agent.id.clone(), Box::new(move || probe.usage_snapshot()));
        Ok(runner)
    })
}

/// Chat-runner profile with the session override applied (feature 5).
fn apply_model_override(mut profile: ModelProfile, ov: &ModelOverride) -> ModelProfile {
    if let Some(model) = &ov.model {
        profile.model = model.clone();
    }
    if let Some(effort) = &ov.effort {
        profile.generation_options.insert("reasoning_effort".into(), json!(effort));
    }
    profile
}

/// CodexOptions for one codex member; the session override wins over the
/// profile model and over the runner's default "xhigh" effort (feature 5).
fn codex_options(
    agent: &AgentSpec,
    profile: Option<&ModelProfile>,
    ov: &ModelOverride,
    session_id: &str,
    cwd: &std::path::Path,
) -> Result<CodexOptions, String> {
    let mut config: Vec<(String, Json)> = vec![];
    let mut model = None;
    if let Some(profile) = profile {
        model = Some(profile.model.clone());
        if !profile.provider.is_empty() {
            config.push(("model_provider".into(), json!(profile.provider)));
        }
        if ov.profile.is_some() && profile.base_url.is_some() {
            // A private provider id avoids inheriting built-in OpenAI auth flags.
            config.retain(|(key, _)| key != "model_provider");
            config.push(("model_provider".into(), json!("teamagents_session")));
            for (key, value) in [("name", json!(profile.provider)), ("base_url", json!(profile.base_url)), ("wire_api", json!("responses"))] {
                config.push((format!("model_providers.teamagents_session.{key}"), value));
            }
            if let Some(env) = &profile.api_key_env {
                config.push(("model_providers.teamagents_session.env_key".into(), json!(env)));
            }
        }
        for (key, value) in &profile.generation_options {
            config.push((key.clone(), value.clone()));
        }
    }
    if let Some(m) = &ov.model {
        model = Some(m.clone());
    }
    Ok(CodexOptions {
        agent_id: agent.id.clone(),
        session_id: session_id.into(),
        workdir: member_root(agent, cwd, session_id)?,
        sandbox: "workspace-write".into(),
        approval_policy: "on-request".into(),
        effort: ov.effort.clone().or_else(|| Some("xhigh".into())),
        model,
        codex_bin: None,
        codex_home: None,
        env: vec![],
        config_overrides: config,
    })
}

/// One executor per member root, refreshed when its config revision changes
/// (members added mid-session resolve on their first tool call).
fn member_executor_factory(
    core: Arc<CoreClient>,
    catalog: UserConfig,
    session_id: String,
    cwd: PathBuf,
) -> ToolExecutor {
    type MemberExecutor = Arc<dyn Fn(&str, &Json, &TurnControl) -> Result<Json, String> + Send + Sync>;
    let cache: Mutex<HashMap<String, (i64, MemberExecutor)>> = Mutex::new(HashMap::new());
    let artifacts = session_paths(&session_id).artifacts;
    Arc::new(move |agent_id: &str, tool: &str, args: &Json, control: &TurnControl| {
        control.check()?;
        // cheap per-call probe; the full state pull below only happens when the
        // executor must be (re)built, not on every tool call (P2-8)
        let revision = core
            .call_in_session("agent_config_revision", json!({"agent_id": agent_id}))?
            .get("config_revision")
            .and_then(|v| v.as_i64())
            .ok_or("bad agent_config_revision response")?;
        let cached = cache.lock().unwrap().get(agent_id).cloned();
        if let Some((cached_revision, executor)) = cached {
            if cached_revision == revision { return executor(tool, args, control); }
        }
        let state = core.call_in_session("state", json!({"include_events": false}))?;
        let agent = state.get("spec").and_then(|spec| spec.get("agents")).cloned()
            .and_then(|agents| serde_json::from_value::<Vec<AgentSpec>>(agents).ok())
            .and_then(|agents| agents.into_iter().find(|a| a.id == agent_id)).ok_or("member is no longer configured")?;
        let executor: MemberExecutor = Arc::new(crate::tools::member_executor_with_control(
            member_root(&agent, &cwd, &session_id)?,
            catalog.clone(),
            agent.tool_bindings.clone(),
            Some(artifacts.clone()),
        ));
        cache.lock().unwrap().insert(agent_id.to_string(), (revision, executor.clone()));
        executor(tool, args, control)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

//! Behavioral checks for the pinned repository task, injected only for grading.
use serde_json::{json, Value};
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, ChildStdin, Command, Stdio};
use std::sync::mpsc::{channel, Receiver};
use std::time::{Duration, Instant};

struct Worker {
    root: PathBuf,
    child: Child,
    stdin: ChildStdin,
    replies: Receiver<Value>,
    reader: Option<std::thread::JoinHandle<()>>,
    next: u64,
}

impl Worker {
    fn new() -> Self {
        Self::start(false)
    }

    fn with_session_profile_only() -> Self {
        Self::start(true)
    }

    fn start(session_only: bool) -> Self {
        let root = std::env::temp_dir().join(format!("ta-fork-hidden-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(root.join("project")).unwrap();
        fs::create_dir_all(root.join("config/teamagents")).unwrap();
        let mut user_config =
            "[models.leader_main]\nprovider=\"openai\"\nprotocol=\"openai\"\nmodel=\"default\"\n".to_string();
        if !session_only {
            user_config.push_str(
                "[models.local]\nprovider=\"openai\"\nprotocol=\"openai\"\nmodel=\"local-default\"\ncontext_window=1000000\n",
            );
        }
        fs::write(root.join("config/teamagents/config.toml"), user_config).unwrap();
        let base = root.join("state/teamagents/sessions/source");
        fs::create_dir_all(&base).unwrap();
        fs::write(
            base.join("profiles.json"),
            json!({"local":{
                "provider":"openai","protocol":"openai","model":"local-default",
                "context_window":1000000
            }})
            .to_string(),
        )
        .unwrap();
        fs::write(root.join("project/user.txt"), "keep user data").unwrap();
        let mut child = Command::new(env!("CARGO_BIN_EXE_teamagents"))
            .arg("serve")
            .env("XDG_STATE_HOME", root.join("state"))
            .env("XDG_CONFIG_HOME", root.join("config"))
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .unwrap();
        let stdout = child.stdout.take().unwrap();
        let stdin = child.stdin.take().unwrap();
        let (tx, replies) = channel();
        let reader = std::thread::spawn(move || {
            for line in BufReader::new(stdout).lines().map_while(Result::ok) {
                let Ok(message) = serde_json::from_str::<Value>(&line) else { continue };
                if message.get("id").is_some() && tx.send(message).is_err() {
                    break;
                }
            }
        });
        let mut worker = Self { root, child, stdin, replies, reader: Some(reader), next: 1 };
        let opened = worker.call("open", json!({
            "cwd":worker.root.join("project"),"resume":"source","fullAuto":true,
            "initial_spec":{"leader_id":"leader","agents":[
                {"id":"leader","name":"Leader","role":"leader","runtime_kind":"deepagents","model_profile":"leader_main","tool_bindings":[]},
                {"id":"worker","name":"Worker","role":"worker","runtime_kind":"deepagents","model_profile":"local","tool_bindings":[]}
            ]},
            "scripts":{"leader":[["end"]],"worker":[["sleep",30],["end"]]}
        })).unwrap();
        assert_eq!(opened["session_id"], "source");
        worker
    }

    fn base(&self, session: &str) -> PathBuf {
        self.root.join("state/teamagents/sessions").join(session)
    }

    fn call(&mut self, method: &str, params: Value) -> Result<Value, String> {
        let id = self.next;
        self.next += 1;
        writeln!(self.stdin, "{}", json!({"id":id,"method":method,"params":params})).unwrap();
        self.stdin.flush().unwrap();
        loop {
            let response = self.replies.recv_timeout(Duration::from_secs(8)).expect("worker response deadline");
            if response["id"] != id {
                continue;
            }
            return match response.get("error").and_then(Value::as_str) {
                Some(error) => Err(error.to_string()),
                None => Ok(response["result"].clone()),
            };
        }
    }

    fn state(&mut self) -> Value {
        self.call("call", json!({"method":"state","params":{"include_events":false}})).unwrap()
    }

    fn set_epoch(&self, epoch: i64) {
        rusqlite::Connection::open(self.base("source").join("team.db"))
            .unwrap()
            .execute(
                "UPDATE agent_runtime SET context_epoch=?1 WHERE session_id='source' AND agent_id='leader'",
                [epoch],
            )
            .unwrap();
    }
}

impl Drop for Worker {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        if let Some(reader) = self.reader.take() {
            let _ = reader.join();
        }
        let _ = fs::remove_dir_all(&self.root);
    }
}

fn model(report: &Value, member: &str) -> Value {
    let row = report["agents"].as_array().unwrap().iter().find(|row| row["agent_id"] == member).unwrap();
    json!({"model_profile":row["model_profile"],"model":row["model"],"effort":row["effort"]})
}

