/// Load persisted overrides, dropping entries that no longer validate against
/// the current spec/models (members or profiles may have changed since).
/// `models` is the session's resolvable set (user config + session profiles),
/// so an override that points at an auto-created member profile (D-30) survives.
fn load_model_overrides(
    session_id: &str,
    models: &std::collections::BTreeMap<String, ModelProfile>,
    agents: &[AgentSpec],
) -> HashMap<String, ModelOverride> {
    let Ok(text) = std::fs::read_to_string(overrides_path(session_id)) else { return HashMap::new() };
    let parsed: HashMap<String, ModelOverride> = serde_json::from_str(&text).unwrap_or_default();
    parsed
        .into_iter()
        .filter(|(id, ov)| {
            let Some(agent) = agents.iter().find(|a| &a.id == id) else { return false };
            let Some(profile) = models.get(ov.profile.as_ref().unwrap_or(&agent.model_profile)) else { return false };
            if ov.profile.is_some() && agent.runtime_kind == RuntimeKind::Codex && profile.protocol != "openai" {
                return false;
            }
            ov.effort.as_ref().is_none_or(|e| model_efforts(&profile.protocol).contains(&e.as_str()))
        })
        .collect()
}

/// Atomic write (tmp + rename) so a reader never sees a half-written file.
fn write_text_atomic(path: &std::path::Path, text: &str) -> Result<(), String> {
    let tmp = path.with_extension("tmp");
    std::fs::write(&tmp, text)
        .and_then(|_| std::fs::rename(&tmp, path))
        .map_err(|e| format!("write {}: {e}", path.display()))
}

